// Club groups. Same list chrome as Events: view menu, search, and New group.
// Membership is people who join the app. This screen never shows a Meetup headcount.
import React, { useCallback, useMemo, useState } from 'react';
import { RefreshControl, View } from 'react-native';
import { router, useFocusEffect } from 'expo-router';
import { EventListRow, useListColumns } from '../../components/events';
import { ListToolbar, MenuActionItem, MenuCheckItem, Popover, useListChrome } from '../../components/list-menu';
import { Button, EmptyState, ErrorText, ListView, Page, PageHeader } from '../../components/ui';
import { PRODUCT_NAME } from '../../lib/config';
import { CLUB_GROUP_SHORT_NAME, GROUP_VIEWS, groupScreenActions, groupsForView, groupViewLabel, type GroupViewId } from '../../lib/group-views';
import { listGroups } from '../../lib/groups';
import { useSession } from '../../lib/session';
import type { ClubGroup } from '../../lib/types';
import type { Column } from '../../components/ui';

const GROUP_COLS: Column[] = [{ label: 'Group', flex: 2 }, { label: 'City', width: 176 }];

export default function Groups() {
  const { userId, isModerator, demo } = useSession();
  const mod = isModerator && !demo && !!userId;
  const actions = groupScreenActions(mod);
  const views = GROUP_VIEWS.filter((view) => view.id === 'active' || mod);
  const [groups, setGroups] = useState<ClubGroup[] | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [view, setView] = useState<GroupViewId>('active');
  const { query: q, setQuery: setQ, searchOpen, menu, anchor, viewBtn, moreBtn, searchRef, closeMenu, openMenu, toggleSearch } = useListChrome();
  const { columns, onLayout } = useListColumns(GROUP_COLS);

  const load = useCallback(async () => {
    setRefreshing(true);
    try {
      setGroups(await listGroups(mod));
      setErr(null);
    } catch (e: any) { setErr(e.message); }
    finally { setRefreshing(false); }
  }, [mod]);
  useFocusEffect(useCallback(() => { if (userId) load(); }, [userId, load]));

  const rows = useMemo(() => (groups ? groupsForView(groups, { view, query: q }) : null), [groups, view, q]);
  const searching = q.trim().length > 0;

  return (
    <Page refreshControl={<RefreshControl refreshing={refreshing} onRefresh={() => load()} />}>
      <PageHeader icon="people" eyebrow={PRODUCT_NAME} title="Groups" subtitle={`${CLUB_GROUP_SHORT_NAME} is the reading club.`} />
      <ErrorText>{err}</ErrorText>
      <View style={{ gap: 8 }}>
        <ListToolbar
          menuLabel={groupViewLabel(view)} menuExpanded={menu === 'views'} onPressMenu={() => openMenu('views')} menuButtonRef={viewBtn}
          searchOpen={searchOpen} onToggleSearch={toggleSearch} searchLabel="Search groups" query={q} onQuery={setQ}
          searchPlaceholder="Search groups…" searchInputRef={searchRef}
          showMore={actions.length > 0} moreExpanded={menu === 'more'} onPressMore={() => openMenu('more')} moreButtonRef={moreBtn}
        />
      </View>
      <View onLayout={onLayout}>
        {!groups && !err ? <ListView loading /> : null}
        {rows && rows.length === 0 ? (
          <ListView empty={<EmptyState icon="people-outline" title={searching ? 'No groups' : view === 'archived' ? 'No archived groups' : 'No groups'}
            body={searching ? 'Nothing matches your search.' : view === 'archived' ? 'Archived groups show up here.' : `Groups on ${PRODUCT_NAME} show up here.`}
            action={!searching && view === 'active' && mod ? <Button small icon="add" title="New group" onPress={() => router.push('/groups/manage/new')} /> : undefined} />} />
        ) : null}
        {rows && rows.length > 0 ? (
          <ListView columns={columns}>
            {rows.map((group) => (
              <EventListRow key={group.id} title={group.name} image={group.image_url} sub={group.slug} when={group.locality ?? '—'}
                dim={group.archived} columns={columns} onPress={() => router.push(`/groups/${group.id}`)}
                accessibilityLabel={`Open ${group.name}`} />
            ))}
          </ListView>
        ) : null}
      </View>
      <Popover visible={menu === 'views'} anchor={anchor} align="left" width={280} onClose={closeMenu}>
        {views.map((option) => (
          <MenuCheckItem key={option.id} label={option.label} selected={option.id === view} onPress={() => { closeMenu(); setView(option.id); }} />
        ))}
      </Popover>
      <Popover visible={menu === 'more'} anchor={anchor} align="right" width={220} onClose={closeMenu}>
        {actions.includes('new') ? (
          <MenuActionItem icon="add" label="New group" onPress={() => { closeMenu(); router.push('/groups/manage/new'); }} />
        ) : null}
      </Popover>
    </Page>
  );
}
